<?= $this->extend('layout') ?><?= $this->section('content') ?>
<section class="panel"><div class="toolbar"><form method="get"><label class="sr-only" for="search">Search by name</label><input id="search" name="q" value="<?= esc($q,'attr') ?>" aria-label="Search by name"><button class="secondary">Search</button><?php if($q): ?><a href="<?= site_url($type) ?>">Clear</a><?php endif ?></form><a class="button" href="<?= site_url($type.'/new') ?>">＋ Add <?= $type==='staff'?'staff':rtrim($type,'s') ?></a></div><div class="table-wrap"><table><thead><tr><th><?= $type==='products'?'Product':'Name' ?></th><?php if($type==='products'): ?><th>Price</th><th>Stock</th><?php elseif($type==='customers'): ?><th>Email</th><th>Phone</th><?php else: ?><th>Username</th><?php endif ?><th>Actions</th></tr></thead><tbody>
<?php foreach($rows as $r): ?><tr><td><div class="identity"><?php $image=$r[$type==='staff'?'avatar':'image']??null; if($image): ?><img src="<?= site_url('media/'.$image) ?>" alt="<?= esc($r['name']??$r['full_name'],'attr') ?>"><?php elseif($type!=='customers'): ?><span class="initial"><?= esc(mb_substr($r['name']??$r['full_name'],0,1)) ?></span><?php endif ?><b><?= esc($r['name']??$r['full_name']) ?></b></div></td>
<?php if($type==='products'): ?><td>₱<?= number_format((float)$r['price'],2) ?></td><td><span class="badge <?= $r['stock_quantity']<=5?'warning':'' ?>"><?= esc($r['stock_quantity']) ?> units</span></td><?php elseif($type==='customers'): ?><td><?= esc($r['email']) ?></td><td><?= esc($r['phone']??'—') ?></td><?php else: ?><td><?= esc($r['username']) ?></td><?php endif ?>
<td><div class="actions"><a href="<?= site_url($type.'/'.$r['id'].'/edit') ?>">Edit</a><form method="post" action="<?= site_url($type.'/'.$r['id'].'/delete') ?>" data-confirm="<?= $type==='products'?'Archive this product?':'Delete this record?' ?> Past sales will be retained."><?= csrf_field() ?><button class="text-danger"><?= $type==='products'?'Archive':'Delete' ?></button></form></div></td></tr><?php endforeach ?>
<?php if(!$rows): ?><tr><td colspan="4" class="empty">No matching records. Add a record to get started.</td></tr><?php endif ?></tbody></table></div><?= $pager->links() ?></section><?= $this->endSection() ?>
